"""Offline catalogue and documentation for the exported world assets."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DOCS = ROOT / 'docs/assets/worlds'
m = json.loads((ROOT / 'assets/environment/worlds/manifest.json').read_text())
levels = json.loads((DOCS / 'level_map.json').read_text())
names = {
    'platform_long':'Dlouhá plošina','ledge':'Krátká římsa','lift_deck':'Pohyblivá podlaha','lift_header':'Horní kladky','pressure_plate':'Nášlapný spínač','gate':'Posuvná brána','hazard':'Past','crumble_platform':'Rozpadající se plošina','repair_socket':'Opravovaný mechanismus',
    'root_workshop':'Dílna pod kořeny','root_arch':'Kořenový oblouk','signpost':'Rozcestník','fern_cluster':'Kapradiny','mushroom_cluster':'Houby','boulder':'Mechový balvan','lantern_post':'Sloup s lucernou','supply_crate':'Bedna se zásobami','root_vine':'Kořenová liána',
    'cottage':'Vesnický domek','guardian_arch':'Brána strážců','watchtower':'Strážní věž','well':'Studna','fence':'Plot','barrels':'Sudy','noticeboard':'Nástěnka','guardian_marker':'Strážní kámen',
    'wind_arch':'Větrná brána','windmill':'Větrný mlýn bez vrtule','cloud_island':'Oblačný ostrůvek','bell_tower':'Zvonice','windsock':'Větrný rukáv','sky_cottage':'Vzdušný domek','anchor':'Kotva ostrovů','cloud_cluster':'Oblak','wind_crystal':'Větrný krystal',
    'royal_arch':'Královský oblouk','prison_cage':'Vězeňská klec','column':'Hradní sloup','banner':'Hvězdný prapor','chandelier':'Lustr','mirror':'Zrcadlo','chest':'Truhla','ivy':'Břečťan','portal_frame':'Rám portálu',
    'giant_flower':'Obří květina','leaf_arch':'Kapradinový průchod','irrigation_pipe':'Zavlažovací potrubí','reservoir':'Vodní nádrž','seed_bed':'Záhon pro semínko','dew_leaf':'List s rosou','root_bundle':'Živé kořeny','thorn_vine':'Trnitá liána','garden_shrine':'Zahradní svatyně',
    'mirror_gate':'Zrcadlová brána','crystal_cluster':'Jeskynní krystaly','river_stone':'Říční kámen','memory_obelisk':'Obelisk vzpomínek','ruined_arch':'Zřícený oblouk','glowing_reeds':'Svítící rákosí','memory_fountain':'Fontána vzpomínek','reflection_frame':'Prázdný rám zrcadla','water_lily':'Leknín',
    'observatory':'Hvězdárna','telescope':'Dalekohled','lantern_house':'Horský domek','star_lamp':'Hvězdná lucerna','alpine_rock':'Horská skála','pine':'Zasněžený smrk','constellation_table':'Hvězdná mapa','empty_lanterns':'Prázdné lucerny','star_shrine':'Hvězdná svatyně',
    'heart_altar':'Oltář tří esencí','magic_conduit':'Přívod magie','shadow_root':'Temný kořen','royal_ruin':'Zbytek hradního sloupu','heart_pedestal':'Podstavec Srdce','service_hatch':'Servisní poklop','light_beacon':'Zachráněné světlo','root_knot':'Kořenový uzel',
    'lever_base':'Základna páky','lever_handle':'Rukojeť páky','gear':'Ozubení pro opravu','chain_link':'Část řetězu','wind_rotor':'Větrná vrtule','spring_pad':'Pružinový mechanismus','valve_wheel':'Kolo ventilu','shadow_lock':'Stínový zámek','checkpoint_lantern':'Lucerna checkpointu',
    'life_drop':'Kapka života','memory_pearl':'Perla vzpomínek','hope_star':'Hvězda naděje','essence_lantern':'Lucerna esencí','last_seed':'Poslední semínko','wind_core':'Větrné jádro','mirror_shard':'Střep zrcadla','star_shard':'Hvězdný úlomek','heart_core':'Srdce království'
}
biomes = {'forest':'Les a kořeny','village':'Vesnice a strážci','sky':'Oblačné ostrovy','castle':'Hrad a vězení','garden':'Zahrady obrů','memory':'Řeka vzpomínek','stars':'Hvězdné hory','heart':'Temnota a Srdce','common':'Společné mechanismy','story':'Příběhové předměty'}
assets=[]
for a in m['assets']:
    a['label']=names[a['name']]
    a['biome_label']=biomes[a['biome']]
    a['scene']='scenes/world_assets/'+a['id']+'.tscn'
    a['category']='Dekorace' if a['kind']=='decor' else 'Předměty' if a['biome']=='story' else 'Pasti' if a['name']=='hazard' else 'Plošiny' if a['name'] in ['platform_long','ledge','lift_deck','crumble_platform'] else 'Mechanismy'
    assets.append(a)
(DOCS/'catalog_data.json').write_text(json.dumps({'assets':assets,'levels':levels,'backgrounds':m['backgrounds']},ensure_ascii=False,indent=2)+'\n')

page='''<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>STARBIT — Atlas světů</title>
<style>
:root{font-family:Inter,Segoe UI,system-ui,sans-serif;color:#e5f0ec;background:#101f2a;color-scheme:dark;--card:#18313e;--ink:#9fbab9}*{box-sizing:border-box}body{margin:0}header{padding:54px max(5vw,24px) 30px;background:radial-gradient(ellipse at 90% 0,#315e61,transparent 60%)}.eyebrow{color:#b8dfbd;letter-spacing:.2em;text-transform:uppercase;font-size:12px}h1{font-size:clamp(38px,6vw,76px);letter-spacing:-.05em;line-height:1;margin:18px 0}header p{color:#b9d0ce;max-width:730px;font-size:17px;line-height:1.65}.stats{display:flex;gap:32px;margin-top:24px}.stats b{display:block;color:#f2d793;font-size:28px}.stats span{font-size:12px;color:var(--ink)}main{padding:20px max(5vw,24px) 60px}.tabs{display:flex;gap:8px;margin:0 0 24px;flex-wrap:wrap}button,select,input{border:1px solid #39545e;border-radius:8px;padding:10px 14px;background:#17313b;color:inherit;font:inherit}button{cursor:pointer}button.active{color:#12232c;background:#cce6ce;border-color:#cce6ce}.toolbar{display:flex;gap:10px;flex-wrap:wrap;position:sticky;top:0;background:#101f2af5;padding:14px 0;z-index:1}input{flex:1;min-width:230px}.count{color:var(--ink);font-size:13px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(225px,1fr));gap:16px}.card{background:var(--card);border-radius:12px;overflow:hidden;border:1px solid #31515b}.image{height:220px;display:flex;align-items:center;justify-content:center;background:#24444d;padding:22px}.light .image{background:#e1e5d4}.image img{max-width:100%;max-height:100%;object-fit:contain;filter:drop-shadow(0 8px 8px #0002)}.body{padding:18px}.tag{font-size:11px;color:#adcbb7;letter-spacing:.06em}h3{font-size:17px;margin:8px 0 4px}.meta{font-size:12px;color:var(--ink);line-height:1.65;overflow-wrap:anywhere}.links{display:flex;gap:16px;margin-top:12px}a{color:#efd592;text-decoration:none;font-size:13px}a:hover{text-decoration:underline}.hidden{display:none!important}.wide{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:20px}.wide img{width:100%;border-radius:10px}.intro{padding:20px 24px;background:#1b3642;border-left:3px solid #e1c98a;border-radius:0 8px 8px 0;color:#c8d9d4;line-height:1.7;margin-bottom:24px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:14px;text-align:left;border-bottom:1px solid #31515b}th{color:#e9d499}td{vertical-align:top}code{font-size:12px;color:#aadacb}footer{color:var(--ink);padding-top:36px;font-size:13px;line-height:1.7}.empty{padding:50px;color:var(--ink)}
</style><header><div class="eyebrow">STARBIT / Království snů</div><h1>Atlas světů.</h1><p>Stavební sada pro příběh od dílny pod kořeny až po Srdce království. Samostatné průhledné objekty, pohyblivé mechanismy a předměty ve společném výtvarném stylu.</p><div class="stats"><div><b>162</b><span>samostatných objektů</span></div><div><b>8</b><span>sad prostředí</span></div><div><b>6</b><span>nových pozadí</span></div><div><b>30</b><span>levelů v rozpisu</span></div></div></header>
<main><nav class="tabs"><button class="active" data-tab="assets">Objekty</button><button data-tab="worlds">Prostředí</button><button data-tab="levels">Rozpis levelů</button><button data-tab="use">Použití v Godotu</button></nav>
<section id="assets"><div class="toolbar"><input id="search" aria-label="Hledat asset" placeholder="Hledat: výtah, lucerna, kořeny…"><select id="biome" aria-label="Prostředí"><option value="">Všechna prostředí</option></select><select id="category" aria-label="Kategorie"><option value="">Všechny kategorie</option><option>Plošiny</option><option>Mechanismy</option><option>Pasti</option><option>Dekorace</option><option>Předměty</option></select><button id="surface">Světlý podklad</button></div><div class="count" id="count"></div><div class="grid" id="cards"></div></section>
<section id="worlds" class="hidden"><div class="intro">Ukázky kombinují skutečné nové objekty s původním Bitem a cílovými pozadími. Jsou to kompozice pro kontrolu grafiky a měřítka; hratelnou zkušebnu otevři v Godotu.</div><div class="wide" id="world-cards"></div><h2>Šest nových pozadí</h2><div class="wide" id="backgrounds"></div></section>
<section id="levels" class="hidden"><div class="intro">Přehled podle nejnovějšího příběhu. Jde o stavební podklady pro 30 levelů. Herní logika příběhu, arény a rozmístění nepřátel se dokončují při stavbě konkrétních levelů.</div><div class="tablewrap"><table><thead><tr><th>Level</th><th>Příběh</th><th>Sada</th><th>Hlavní objekty</th></tr></thead><tbody id="level-rows"></tbody></table></div></section>
<section id="use" class="hidden"><div class="intro"><strong>Rychlý start:</strong> Zkopíruj složky balíčku do existujícího projektu STARBIT. V Godotu 4.7.2 otevři <code>scenes/showcases/WorldAssets.tscn</code> a stiskni F6. Klávesami 1–8 přepínáš prostředí; A/D nebo šipkami chodíš, mezerníkem skáčeš a E sbíráš, opravuješ a aktivuješ.</div><p>Jednotlivé scény najdeš v <code>scenes/world_assets/</code>. Přetáhni scénu z panelu FileSystem do levelu. PNG jsou v <code>assets/environment/worlds/</code>.</p><p>Každá sada má složený výtah <code>Lift.tscn</code>. Na uzlu Deck nastav dráhu <code>travel</code> a dobu <code>period</code>. Nášlapné spínače a páka mají seznam cílů <code>targets</code>. Brána i výtah přijímají <code>set_powered(bool)</code>.</p><p>Plošiny mají počátek na nášlapné hraně, dekorace u paty. Obrázky mají zachovaný poměr stran a osm průhledných pixelů kolem obrysu. Jsou to celé samostatné plošiny; jejich konce nejsou bezešvé dlaždice.</p><p>Skutečné animace Bita, životy a inventář používají existující systém hry. Pružina, ventil, řetěz, lucerna checkpointu a zrcadla jsou připravené výtvarné díly; jejich specifické chování doplníš podle konkrétního levelu. Nové animace postav nebo bossů tento balíček neobsahuje.</p><p><a href="README.md">Podrobný návod</a> · <a href="LEVEL_MAP.md">Rozpis všech levelů</a> · <a href="ART_NOTES.md">Původ a pravidla grafiky</a></p></section>
<footer>STARBIT · Grafika vytvořená a rozdělená v Higgsfieldu podle referencí existující hry. Říjen 2026.</footer></main>
<script>const DATA=__DATA__;const BIOMES=__BIOMES__;const path=p=>'../../../'+p;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const el=id=>document.getElementById(id);Object.entries(BIOMES).forEach(([k,v])=>el('biome').add(new Option(v,k)));
function render(){const q=el('search').value.toLocaleLowerCase('cs'),b=el('biome').value,c=el('category').value;const shown=DATA.assets.filter(a=>(!b||a.biome===b)&&(!c||a.category===c)&&(!q||[a.label,a.id,a.biome_label,a.category].join(' ').toLocaleLowerCase('cs').includes(q)));el('count').textContent=shown.length+' / 162 objektů';el('cards').innerHTML=shown.length?shown.map(a=>`<article class="card"><div class="image"><img loading="lazy" src="${path(a.path)}" alt="${esc(a.label)}"></div><div class="body"><div class="tag">${esc(a.biome_label)} / ${esc(a.category)}</div><h3>${esc(a.label)}</h3><div class="meta">${a.size.join(' × ')} px · PNG s průhledností<br>${esc(a.id)}</div><div class="links"><a href="${path(a.path)}" download>PNG ↓</a><a href="${path(a.scene)}" download>Scéna .tscn ↓</a></div></div></article>`).join(''):'<div class="empty">Žádný objekt neodpovídá filtru.</div>'}
['search','biome','category'].forEach(id=>el(id).addEventListener('input',render));el('surface').onclick=()=>{const light=document.body.classList.toggle('light');el('surface').textContent=light?'Tmavý podklad':'Světlý podklad'};document.querySelectorAll('[data-tab]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b===btn));['assets','worlds','levels','use'].forEach(id=>el(id).classList.toggle('hidden',id!==btn.dataset.tab))});
el('world-cards').innerHTML=Object.entries(BIOMES).slice(0,8).map(([k,v])=>`<article><img loading="lazy" src="previews/scale_${k}.jpg" alt="${esc(v)}"><h3>${esc(v)}</h3><a href="../../../scenes/world_assets/${k}/Lift.tscn" download>Výtah pro toto prostředí ↓</a></article>`).join('');el('backgrounds').innerHTML=DATA.backgrounds.map(b=>`<article><a href="${path(b.path)}"><img loading="lazy" src="${path(b.path)}" alt="${esc(b.title)}"></a><h3>${esc(b.title)}</h3><p class="meta">${b.size.join(' × ')} px · celé pozadí</p></article>`).join('');el('level-rows').innerHTML=DATA.levels.map(l=>`<tr><td>${l.level}</td><td><strong>${esc(l.title)}</strong><p class="meta">${esc(l.purpose)}</p></td><td>${esc(BIOMES[l.biome])}</td><td><code>${esc(l.key_assets).replaceAll(',',', ')}</code></td></tr>`).join('');render();</script></html>'''
data={'assets':assets,'levels':levels,'backgrounds':m['backgrounds']}
page=page.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')).replace('__BIOMES__',json.dumps(biomes,ensure_ascii=False))
(DOCS/'KATALOG.html').write_text(page)
print('Catalogue: 162 labelled objects, 30 level mappings, 8 scale previews, 6 backgrounds.')
